import { HttpClient } from '@angular/common/http';
import { Injectable } from '@angular/core';
import { Observable } from 'rxjs';
import { party } from '../pages/party/party';
import { environment } from '../environments/environments';
@Injectable({
  providedIn: 'root'
})
export class PartyService {
  private ApiUrl = `${environment.apiUrl}/party/`;

  constructor(private http: HttpClient) {}

  getParties(): Observable<party[]>{
    return this.http.get<party[]>(`${this.ApiUrl}getallparty`);
  }

  CreateParties(party: party): Observable<party> {
  return this.http.post<party>(`${this.ApiUrl}create-party`, party);
}
  getPartyById(id: number): Observable<party> {
  return this.http.get<party>(`${this.ApiUrl}getparty/${id}`);
}

  editParty(id: number, party: party): Observable<party> {
  return this.http.put<party>(`${this.ApiUrl}edit-party/${id}`, party);
}
}
